SELECT CAST(SUM(CASE WHEN LOWER(Co.Country_Name) = 'india' THEN 1 ELSE 0 END) AS REAL) / SUM(CASE WHEN LOWER(Co.Country_Name) = 'south africa' THEN 1 ELSE 0 END) AS ratio
